<script>
 import PdfStoryImport from './PdfStoryImport.svelte';
 import {Sparkles,PenLine,ArrowRight} from 'lucide-svelte';
 let {oncreate,oncancel}=$props();
 let pdfMode=$state(false);
 let mode=$state('manual'),title=$state(''),story=$state(''),cast=$state(''),places=$state(''),scenes=$state([]),review=$state(false),error=$state('');
 function analyze(){if(!story.trim()){error='Paste a story to create an editable breakdown.';return;}const pieces=story.split(/\n(?=(?:SCENE\s+\d+|INT\.|EXT\.|CHAPTER\s+\d+|#{1,3}\s))/i).filter(Boolean);const chunks=pieces.length>1?pieces:story.split(/\n\s*\n/).filter(Boolean);scenes=chunks.map((text,i)=>({title:/^(?:SCENE|INT\.|EXT\.|CHAPTER|#)/i.test(text.trim())?text.trim().split('\n')[0].replace(/^#+\s*/, ''):'Moment '+(i+1),text:text.trim()}));review=true;error='';}
 function submit(){if(!title.trim()){error='Give your story a name.';return;}oncreate({title:title.trim(),mode,characters:cast.split('\n').filter(x=>x.trim()).map(line=>{const [name,...d]=line.split(':');return{name:name.trim(),description:d.join(':').trim()||'Develop this character’s appearance, personality and role.'};}),locations:places.split('\n').filter(x=>x.trim()).map(line=>{const [name,...d]=line.split(':');return{name:name.trim(),description:d.join(':').trim()||'Develop the architecture, geography, light and atmosphere.'};}),scenes:mode==='manual'?[{title:'Opening moment',text:''}]:scenes});}
</script>
<div class="story-creator">{#if pdfMode}<PdfStoryImport {oncreate} oncancel={()=>pdfMode=false}/>{:else}<span class="eyebrow">A NEW STORY SPACE</span><h2>Every world starts somewhere.</h2><div class="creation-methods"><button class:chosen={mode==='manual'} onclick={()=>{mode='manual';review=false;}}><PenLine size={22}/><strong>Build manually</strong><span>Create the people, places and moments yourself.</span></button><button class:chosen={mode==='assisted'} onclick={()=>mode='assisted'}><Sparkles size={22}/><strong>Assisted story breakdown</strong><span>Paste a story and review an editable draft outline.</span></button></div><button class="button secondary import-pdf-entry" onclick={()=>pdfMode=true}>Import a full story PDF <ArrowRight size={14}/></button><label class="director-field">Story name<input bind:value={title} placeholder="The world you're about to create"/></label>{#if mode==='assisted'}<div class="generation-warning"><span><strong>Local outline parser, not AI analysis</strong><small>No language-model provider is connected. Scene headings and paragraphs are split into drafts; you review characters and locations. No image generation is triggered.</small></span></div><label class="director-field">Your story<textarea class="story-import-text" bind:value={story} placeholder="Paste the story. Use SCENE headings or paragraph breaks to mark moments."></textarea></label><button class="button secondary" onclick={analyze}>Prepare draft breakdown <Sparkles size={14}/></button>{#if review}<p>{scenes.length} draft scenes. Short descriptions remain drafts until they reach 100 words.</p>{#each scenes as scene,i}<details><summary>Scene {i+1} · {scene.title}</summary><label class="director-field">Title<input bind:value={scene.title}/></label><label class="director-field">Description<textarea bind:value={scene.text}></textarea></label></details>{/each}<label class="director-field">Character records, one per line<textarea bind:value={cast} placeholder="Name: appearance, personality, clothing and role"></textarea></label><label class="director-field">Location records, one per line<textarea bind:value={places} placeholder="Location name: visual description and atmosphere"></textarea></label>{/if}{/if}{#if error}<p class="director-error" role="alert">{error}</p>{/if}<div class="form-actions"><button class="button secondary" onclick={oncancel}>Cancel</button><button class="button primary" disabled={mode==='assisted'&&!review} onclick={submit}>Create story space <ArrowRight size={14}/></button></div>{/if}</div>
